solution.ShoppingCart.java:
import java.util.ArrayList;
import java.util.List;

public class ShoppingCart {
    private final List<Item> items = new ArrayList<>();

    private Item find(String name) {
        for (Item item : items) {
            if (item.name.equalsIgnoreCase(name)) return item;
        }
        return null;
    }

    void add(String name, int priceCents, int quantity) {
        if (name == null || name.isBlank()) throw new IllegalArgumentException("blank name");
        if (priceCents < 0) throw new IllegalArgumentException("negative price");
        if (quantity < 1) throw new IllegalArgumentException("quantity must be at least 1");
        Item existing = find(name);
        if (existing == null) {
            items.add(new Item(name, priceCents, quantity));
        } else if (existing.priceCents != priceCents) {
            throw new IllegalArgumentException("price differs for " + name);
        } else {
            existing.quantity += quantity;
        }
    }

    boolean remove(String name) {
        Item item = find(name);
        return item != null && items.remove(item);
    }

    int itemCount() {
        int count = 0;
        for (Item item : items) count += item.quantity;
        return count;
    }

    long totalCents() {
        long total = 0;
        for (Item item : items) total += (long) item.priceCents * item.quantity;
        return total;
    }

    private static String euros(long cents) {
        return String.format("%d.%02d", cents / 100, cents % 100);
    }

    String receipt() {
        StringBuilder sb = new StringBuilder();
        for (Item item : items) {
            sb.append(item.name).append(" x").append(item.quantity).append(' ')
              .append(euros((long) item.priceCents * item.quantity)).append('\n');
        }
        sb.append("Total: ").append(euros(totalCents())).append('\n');
        return sb.toString();
    }
}

class Item {
    final String name;
    final int priceCents;
    int quantity;

    Item(String name, int priceCents, int quantity) {
        this.name = name;
        this.priceCents = priceCents;
        this.quantity = quantity;
    }
}

unitTests:
test("adding and totals", () -> {
    ShoppingCart cart = new ShoppingCart();
    cart.add("Tea", 250, 2);
    cart.add("Cake", 425, 1);
    cart.add("tea", 250, 1);
    checkEq(cart.itemCount(), 4);
    checkEq(cart.totalCents(), 1175L);
    checkEq(cart.receipt(), "Tea x3 7.50\nCake x1 4.25\nTotal: 11.75\n");
});

test("removing", () -> {
    ShoppingCart cart = new ShoppingCart();
    cart.add("Mug", 800, 1);
    cart.add("Pen", 120, 5);
    checkEq(cart.remove("MUG"), true);
    checkEq(cart.remove("Mug"), false);
    checkEq(cart.receipt(), "Pen x5 6.00\nTotal: 6.00\n");
    checkEq(new ShoppingCart().receipt(), "Total: 0.00\n");
});

test("invalid input", () -> {
    ShoppingCart cart = new ShoppingCart();
    checkThrows(IllegalArgumentException.class, () -> cart.add(" ", 100, 1));
    checkThrows(IllegalArgumentException.class, () -> cart.add("A", -1, 1));
    checkThrows(IllegalArgumentException.class, () -> cart.add("A", 100, 0));
    cart.add("A", 100, 1);
    checkThrows(IllegalArgumentException.class, () -> cart.add("a", 150, 1));
    checkEq(cart.itemCount(), 1);
});

test("separate carts", () -> {
    ShoppingCart a = new ShoppingCart(), b = new ShoppingCart();
    a.add("Tea", 250, 1);
    checkEq(b.itemCount(), 0);
    a.add("Big", 1_000_000_000, 3);
    checkEq(a.totalCents(), 3_000_000_250L);
});

